<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import type {EChartsOption} from 'echarts'
import PageHeader from '@/components/PageHeader.vue';import LoadingState from '@/components/LoadingState.vue';import EmptyState from '@/components/EmptyState.vue';import ErrorState from '@/components/ErrorState.vue';import BaseChart from '@/components/BaseChart.vue';import StatusTag from '@/components/StatusTag.vue'
import {useSiteStore} from '@/stores/site';import {scenariosApi} from '@/api/scenarios';import {simulationApi} from '@/api/simulation';import {risksApi} from '@/api/risks'
import type {RiskAssessment,RiskAssessmentCreate,RiskLevel,Scenario,ScenarioVersion,SimulationBatch} from '@/types'
const route=useRoute(),router=useRouter(),siteStore=useSiteStore(),loading=ref(true),busy=ref(false),error=ref<string|null>(null),operationError=ref<string|null>(null);const scenarios=ref<Scenario[]>([]),versions=ref<ScenarioVersion[]>([]),batches=ref<SimulationBatch[]>([]),runs=ref<RiskAssessment[]>([]),selected=ref<RiskAssessment|null>(null),versionId=ref<number|null>(null),taskId=ref<number|null>(null),dates=ref<[Date,Date]|null>(null)
const form=ref<RiskAssessmentCreate>({scenario_version_id:0,simulation_task_id:0,simulation_year:new Date().getFullYear(),price_volatility_pct:0,renewable_volatility_pct:0,technical_implementation_score:1});const categoryLabels:Record<string,string>={PEAK_DELAY:'达峰延期风险',NEUTRALITY_DELAY:'中和延期风险',INVESTMENT_PAYBACK:'投资回收风险',PRICE_VOLATILITY:'电价/碳价波动风险',RENEWABLE_VOLATILITY:'可再生能源波动风险',TECHNICAL_IMPLEMENTATION:'技术实施风险'},levelScore:Record<RiskLevel,number>={LOW:1,MEDIUM:2,HIGH:3},levelLabels:Record<RiskLevel,string>={LOW:'低风险',MEDIUM:'中风险',HIGH:'高风险'}
const tasks=computed(()=>batches.value.flatMap(b=>b.items).filter(i=>i.scenario_version_id===versionId.value&&i.task_id).map(i=>({id:i.task_id!,batchItemId:i.id,label:`Task #${i.task_id} · ${i.status}`})).filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i));const counts=computed(()=>({HIGH:selected.value?.results.filter(x=>x.level==='HIGH').length||0,MEDIUM:selected.value?.results.filter(x=>x.level==='MEDIUM').length||0,LOW:selected.value?.results.filter(x=>x.level==='LOW').length||0}));const scenarioName=(id:number)=>{const v=versions.value.find(x=>x.id===id),s=scenarios.value.find(x=>x.id===v?.scenario_id);return s?.name||`Version #${id}`};const indicator=(v:unknown)=>typeof v==='object'?JSON.stringify(v):v==null?'暂无数据':String(v)
const riskOption=computed<EChartsOption>(()=>({grid:{left:100,right:20,top:40,bottom:45},xAxis:{type:'category',axisLabel:{rotate:15},data:(selected.value?.results||[]).map(x=>categoryLabels[x.category]||x.category)},yAxis:{type:'value',min:0,max:3,interval:1,axisLabel:{formatter:(v:number)=>['','低','中','高'][v]}},series:[{name:'风险等级',type:'bar',data:(selected.value?.results||[]).map(x=>({value:levelScore[x.level],itemStyle:{color:x.level==='HIGH'?'#bf5151':x.level==='MEDIUM'?'#d49a3a':'#438b6c'}}))}]}));const distributionOption=computed<EChartsOption>(()=>({series:[{name:'风险分布',type:'pie',radius:['40%','70%'],data:[{name:'高风险',value:counts.value.HIGH},{name:'中风险',value:counts.value.MEDIUM},{name:'低风险',value:counts.value.LOW}]}]}));const comparisonRuns=computed(()=>{const seen=new Set<number>();return runs.value.filter(x=>!seen.has(x.scenario_version_id)&&seen.add(x.scenario_version_id))});const comparisonOption=computed<EChartsOption>(()=>({legend:{},grid:{left:80,right:20,top:45,bottom:80},xAxis:{type:'category',axisLabel:{rotate:18},data:Object.values(categoryLabels)},yAxis:{type:'value',min:0,max:3,interval:1,axisLabel:{formatter:(v:number)=>['','低','中','高'][v]}},series:comparisonRuns.value.map(run=>({name:scenarioName(run.scenario_version_id),type:'bar',data:Object.keys(categoryLabels).map(c=>{const r=run.results.find(x=>x.category===c);return r?levelScore[r.level]:null})}))}))
async function initialize(){loading.value=true;error.value=null;try{await siteStore.loadSites();if(!siteStore.currentSite)return;scenarios.value=await scenariosApi.list(siteStore.currentSite.enterprise_id);versions.value=(await Promise.all(scenarios.value.map(s=>scenariosApi.versions(s.id)))).flat();batches.value=await simulationApi.batches(siteStore.currentSite.enterprise_id);versionId.value=Number(route.query.scenario_version)||versions.value.at(-1)?.id||null;taskId.value=Number(route.query.task)||null;await loadRuns()}catch(e){error.value=(e as {message?:string}).message||'风险页面加载失败'}finally{loading.value=false}}
async function loadRuns(){const [start,end]=dates.value||[];runs.value=await risksApi.list({start:start?.toISOString(),end:end?.toISOString()});selected.value=runs.value.find(x=>x.scenario_version_id===versionId.value&&(!taskId.value||x.simulation_task_id===taskId.value))||null}
async function assess(){if(!versionId.value||!taskId.value)return;busy.value=true;operationError.value=null;try{const task=tasks.value.find(x=>x.id===taskId.value);const payload={...form.value,scenario_version_id:versionId.value,simulation_task_id:taskId.value,batch_item_id:task?.batchItemId};selected.value=await risksApi.create(payload);runs.value=[selected.value,...runs.value]}catch(e){operationError.value=(e as {message?:string}).message||'风险评估失败'}finally{busy.value=false}}
watch(versionId,()=>{taskId.value=tasks.value[0]?.id||null;selected.value=runs.value.find(x=>x.scenario_version_id===versionId.value)||null});watch(taskId,()=>selected.value=runs.value.find(x=>x.scenario_version_id===versionId.value&&x.simulation_task_id===taskId.value)||null);onMounted(initialize)
</script>
<template><section><PageHeader kicker="RISK ASSESSMENT" title="场景风险识别与比较" description="严格展示 RiskAssessmentEngine 输出的六类风险，不在前端重判风险等级。"><el-button :loading="loading" @click="initialize">刷新</el-button></PageHeader><LoadingState v-if="loading"/><ErrorState v-else-if="error" :message="error" @retry="initialize"/><template v-else-if="siteStore.currentSite"><article class="panel context-bar"><el-select v-model="versionId" placeholder="ScenarioVersion"><el-option v-for="v in versions" :key="v.id" :value="v.id" :label="`${scenarioName(v.id)} · V${v.version_number} · #${v.id}`"/></el-select><el-select v-model="taskId" placeholder="SimulationTask"><el-option v-for="t in tasks" :key="t.id" :value="t.id" :label="t.label"/></el-select><el-date-picker v-model="dates" type="datetimerange"/><el-button @click="loadRuns">查询历史</el-button></article><article class="panel risk-form"><div class="panel-head"><div><span>FROZEN INPUT</span><h2>发起风险评估</h2></div><el-button type="primary" :loading="busy" :disabled="!versionId||!taskId" @click="assess">执行六类风险评估</el-button></div><div class="form-grid"><label>仿真年份<el-input-number v-model="form.simulation_year"/></label><label>减排率（可选）<el-input-number v-model="form.reduction_rate" :step=".01"/></label><label>回收期（可选）<el-input-number v-model="form.payback_years" :step=".5"/></label><label>电价/碳价波动 %<el-input-number v-model="form.price_volatility_pct"/></label><label>可再生能源波动 %<el-input-number v-model="form.renewable_volatility_pct"/></label><label>技术实施评分<el-input-number v-model="form.technical_implementation_score" :min="0" :max="1" :step=".1"/></label></div><el-alert v-if="operationError" :title="operationError" type="error" :closable="false"/></article>
<template v-if="selected"><section class="market-cards"><article><span>最高风险等级</span><StatusTag :status="selected.overall_level"/><b>{{levelLabels[selected.overall_level]}}</b></article><article><span>高风险</span><b>{{counts.HIGH}}</b></article><article><span>中风险</span><b>{{counts.MEDIUM}}</b></article><article><span>低风险</span><b>{{counts.LOW}}</b></article><article><span>ScenarioVersion</span><b>#{{selected.scenario_version_id}}</b></article><article><span>SimulationTask</span><b>#{{selected.simulation_task_id}}</b></article></section><div class="chart-grid"><article class="panel"><h2>六类风险等级</h2><BaseChart :option="riskOption"/></article><article class="panel"><h2>风险分布</h2><BaseChart :option="distributionOption"/></article></div><article class="panel"><div class="panel-head"><div><span>RISK DETAILS</span><h2>风险明细与建议</h2></div><span>{{new Date(selected.created_at).toLocaleString('zh-CN')}}</span></div><el-table :data="selected.results" border><el-table-column label="风险类别" width="180"><template #default="{row}">{{categoryLabels[row.category]||row.category}}</template></el-table-column><el-table-column label="等级" width="110"><template #default="{row}"><StatusTag :status="row.level"/> {{levelLabels[row.level as RiskLevel]}}</template></el-table-column><el-table-column label="指标值"><template #default="{row}">{{indicator(row.indicator_value)}}</template></el-table-column><el-table-column prop="trigger_reason" label="触发原因"/><el-table-column prop="recommendation" label="建议"/></el-table></article><article class="panel trace"><h2>历史快照追溯</h2><p>Scenario #{{versions.find(v=>v.id===selected?.scenario_version_id)?.scenario_id}} · ScenarioVersion #{{selected.scenario_version_id}} · SimulationTask #{{selected.simulation_task_id}} · 评估 #{{selected.id}}</p><pre>{{JSON.stringify(selected.input_snapshot_json,null,2)}}</pre><el-alert title="历史结果基于任务执行时冻结快照，不读取当前风险参数替换历史结果。" type="info" :closable="false"/><el-button type="primary" @click="router.push({path:'/reports',query:{scenario_version:selected.scenario_version_id,task:selected.simulation_task_id}})">生成可行性报告</el-button></article></template><EmptyState v-else title="当前场景尚未进行风险评估" description="未评估不等于低风险"/>
<article class="panel"><div class="panel-head"><div><span>SCENARIO COMPARISON</span><h2>场景风险比较</h2></div><span>无评估结果的场景显示“未评估”</span></div><BaseChart v-if="comparisonRuns.length" :option="comparisonOption"/><el-table :data="versions"><el-table-column label="场景"><template #default="{row}">{{scenarioName(row.id)}}</template></el-table-column><el-table-column v-for="(label,key) in categoryLabels" :key="key" :label="label"><template #default="{row}">{{levelLabels[comparisonRuns.find(x=>x.scenario_version_id===row.id)?.results.find(x=>x.category===key)?.level as RiskLevel]||'未评估'}}</template></el-table-column><el-table-column label="高风险数"><template #default="{row}">{{comparisonRuns.find(x=>x.scenario_version_id===row.id)?.results.filter(x=>x.level==='HIGH').length??'未评估'}}</template></el-table-column></el-table></article><article class="panel"><h2>历史评估</h2><el-table :data="runs" @row-click="(row:RiskAssessment)=>selected=row"><el-table-column prop="id" label="Run ID"/><el-table-column label="场景"><template #default="{row}">{{scenarioName(row.scenario_version_id)}}</template></el-table-column><el-table-column prop="simulation_task_id" label="Task ID"/><el-table-column label="最高等级"><template #default="{row}"><StatusTag :status="row.overall_level"/></template></el-table-column><el-table-column label="评估时间"><template #default="{row}">{{new Date(row.created_at).toLocaleString('zh-CN')}}</template></el-table-column></el-table></article></template><EmptyState v-else title="暂无 Site"/></section></template>
